package com.bankease.exception; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*; @RestControllerAdvice public class GlobalExceptionHandler{private Map<String,Object> body(String msg){return Map.of("timestamp",Instant.now().toString(),"message",msg);} @ExceptionHandler(NoSuchElementException.class)ResponseEntity<?> notFound(NoSuchElementException e){return ResponseEntity.status(404).body(body(e.getMessage()));}@ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class})ResponseEntity<?> bad(RuntimeException e){return ResponseEntity.badRequest().body(body(e.getMessage()));}@ExceptionHandler(SecurityException.class)ResponseEntity<?> forbidden(SecurityException e){return ResponseEntity.status(403).body(body(e.getMessage()));}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<?> validation(MethodArgumentNotValidException e){String m=e.getBindingResult().getFieldErrors().stream().findFirst().map(x->x.getField()+": "+x.getDefaultMessage()).orElse("Invalid request");return ResponseEntity.badRequest().body(body(m));}}